import heapq


def quota_intervals(capacity, tie):
    def solve(data):
        k = data["k"]
        blocked = set(data.get("blocked", []))
        mandatory = set(data.get("mandatory", []))
        quotas = data.get("quotas", {})
        jobs = [j for j in data["jobs"] if j["id"] not in blocked]
        best_value = None
        best_ids = None
        for chosen in combinations(jobs, k):
            ids = sorted(j["id"] for j in chosen)
            idset = set(ids)
            if not mandatory.issubset(idset):
                continue
            counts = {}
            for job in chosen:
                counts[job["group"]] = counts.get(job["group"], 0) + 1
            if any(not low <= counts.get(group, 0) <= high
                   for group, (low, high) in quotas.items()):
                continue
            if any(sum(j["start"] <= t < j["end"] for j in chosen) > capacity
                   for t in {j["start"] for j in chosen}):
                continue
            value = sum(j["value"] for j in chosen)
            if (best_value is None or value > best_value or
                (value == best_value and
                 (ids > best_ids if tie == "largest" else ids < best_ids))):
                best_value, best_ids = value, ids
        if best_value is None:
            return {"error": "impossible"}
        return {"selected": best_ids, "value": best_value}
    return solve


def ledger(data):
    cutoff = data.get("cutoff", 10**9)
    winners = {}
    for pos, event in enumerate(data["events"]):
        seq = event.get("sequence", 0)
        if seq > cutoff:
            continue
        ident = event.get("id", "anonymous:" + str(pos))
        key = (seq, event.get("revision", 0), pos)
        if ident not in winners or key > winners[ident][0]:
            winners[ident] = (key, event)

    balances = dict(data.get("opening", {}))
    den = 10000
    def rounded(n, mode):
        if mode == "half_up":
            return (n + den // 2) // den
        return n // den

    mode = data["rounding"]
    for _, event in winners.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (den - discount), mode)
        tax = rounded(raw * event.get("tax_bp", 0), mode)
        amount = net + tax
        if event.get("kind") == "refund":
            amount = -amount
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + amount
    return {"balances": balances}


def dependencies(data):
    packages = data["packages"]
    names = sorted(packages, reverse=True)
    features = set(data.get("features", []))
    roots = data["roots"]
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    choices = []
    for name in names:
        choices.append([-1] + [row["version"] for row in packages[name]])

    best_score = None
    best = None
    for vals in product(*choices):
        selected = {name: v for name, v in zip(names, vals) if v != -1}
        if any(name not in selected or not low <= selected[name] <= high
               for name, (low, high) in roots.items()):
            continue
        if any(name in selected and selected[name] in blocked.get(name, [])
               for name in names):
            continue
        if any(name in selected and selected[name] != version
               for name, version in pins.items()):
            continue
        rows = {name: next(r for r in packages[name] if r["version"] == version)
                for name, version in selected.items()}
        edges = {name: [] for name in selected}
        valid = True
        for name, row in rows.items():
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                other = dep["name"]
                if other not in selected or not dep["min"] <= selected[other] <= dep["max"]:
                    valid = False
                    break
                edges[name].append(other)
            if not valid:
                break
        if not valid:
            continue

        # The installation must be precisely the active closure of its roots.
        reachable = set()
        pending = list(roots)
        while pending:
            name = pending.pop()
            if name in reachable:
                continue
            if name not in selected:
                valid = False
                break
            reachable.add(name)
            pending.extend(edges[name])
        if not valid or reachable != set(selected):
            continue

        finished, active = set(), set()
        def visit(name):
            if name in active:
                return False
            if name in finished:
                return True
            active.add(name)
            if not all(visit(other) for other in edges[name]):
                return False
            active.remove(name)
            finished.add(name)
            return True
        if not all(visit(name) for name in selected):
            continue
        score = tuple(selected.get(name, -1) for name in names)
        if best_score is None or score > best_score:
            best_score, best = score, selected
    if best is None:
        return {"error": "unsatisfiable"}
    return {"versions": best}


def temporal(data):
    required = data.get("required", [])
    full = (1 << len(required)) - 1
    initial_mask = sum(1 << i for i, node in enumerate(required)
                       if node == data["source"])
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)
    start_state = (data["source"], initial_mask, data["coupons"])
    start = data["start"]
    dist = {start_state: start}
    queue = [(start, *start_state)]
    while queue:
        time, node, mask, remaining = heapq.heappop(queue)
        state = (node, mask, remaining)
        if dist.get(state) != time:
            continue
        if node == data["target"] and mask == full and remaining == 0:
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            durations = [(edge["duration"], remaining)]
            if remaining:
                durations.append((max(1, edge["duration"] - edge.get("discount", 0)), remaining - 1))
            for duration, left in durations:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                nxt = edge["v"]
                next_mask = mask
                for i, node_id in enumerate(required):
                    if node_id == nxt:
                        next_mask |= 1 << i
                next_state = (nxt, next_mask, left)
                if arrival < dist.get(next_state, float("inf")):
                    dist[next_state] = arrival
                    heapq.heappush(queue, (arrival, *next_state))
    return {"arrival": None}


